        return []

    # Find the minimum start and maximum end to determine the range
    min_start = min(i[0] for i in intervals)
    max_end = max(i[1] for i in intervals)

    # Initialize a list to track merged intervals
    merged = []

    # Iterate through each possible start and end point
    for start in range(min_start, max_end + 1):
        # Check if this start is the beginning of an interval
        if any(i[0] == start for i in intervals):
            # Find the corresponding end
            end = next(i[1] for i in intervals if i[0] == start)
            # Extend end as far as possible
            while any(i[0] <= end + 1 and i[1] >= end for i in intervals):
                end = max(end, next(i[1] for i in intervals if i[0] <= end + 1 and i[1] >= end))
            merged.append([start, end])

    # Sort the merged intervals by start
    merged.sort()
    return merged
